contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address a, address b) public payable {
        uint256 preCallerBal = c.balances(a); if (__ESBMC_reverted()) return;
        uint256 preOtherBal = c.balances(b); if (__ESBMC_reverted()) return;
        uint256 preReserve = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted
                ? (preCallerBal != 0 && preCallerBal > preReserve)
                : (c.balances(a) == 0 && address(c).balance == preReserve - preCallerBal && c.balances(b) == preOtherBal)
        );
    }

    receive() external payable {}
}

