        c = new keepMyEther();
    }

    function _run(address a, address b) internal {
        uint256 preCallerBal;
        try c.balances(a) returns (uint256 __r) { preCallerBal = __r; } catch { return; }
        uint256 preOtherBal;
        try c.balances(b) returns (uint256 __r) { preOtherBal = __r; } catch { return; }
