            reverted = true;
        }
        assertTrue(reverted
                ? (preCallerBal != 0 && preCallerBal > preReserve)
                : (c.balances(a) == 0 && address(c).balance == preReserve - preCallerBal && c.balances(b) == preOtherBal));
    }

